24	/// A worker that manages the individual tool for a specific workspace
25	/// and returns back the results of the running tool.
26	///
27	/// Each worker is responsible for a specific root URI and configures the tool's `cwd` to that root URI.
28	/// The [`WorkerManager`](crate::worker_manager::WorkerManager) is responsible to target the correct worker for a given file URI.
29	pub struct WorkspaceWorker {
30	    root_uri: Uri,
31	    tool: RwLock<Option<Box<dyn Tool>>>,
32	    builder: Arc<dyn ToolBuilder>,
33	    // Initialized options from the client
34	    // If None, the worker has not been initialized yet
35	    pub(crate) options: Mutex<Option<serde_json::Value>>,
36	
37	    // Whether the client is in diagnostic pull mode / push mode, or not supporting diagnostics at all
38	    diagnostic_mode: DiagnosticMode,
39	    // Keep track of published diagnostics to clear them on shutdown (only in push mode)
40	    published_diagnostics: Mutex<FxHashSet<Uri>>,
41	}
42	
43	impl WorkspaceWorker {
44	    /// Create a new workspace worker.
45	    /// This will not start any programs, use [`start_worker`](Self::start_worker) for that.
46	    /// Depending on the client, we need to request the workspace configuration in `initialized` request.
47	    pub fn new(
48	        root_uri: Uri,
49	        builder: Arc<dyn ToolBuilder>,
50	        diagnostic_mode: DiagnosticMode,
51	    ) -> Self {
52	        Self {
53	            root_uri,
54	            tool: RwLock::new(None),
55	            builder,
56	            options: Mutex::new(None),
57	            diagnostic_mode,
58	            published_diagnostics: Mutex::new(FxHashSet::default()),
59	        }
60	    }
61	
62	    /// Get the root URI of the worker
63	    pub fn get_root_uri(&self) -> &Uri {
64	        &self.root_uri
65	    }
66	
67	    /// Start all programs (linter, formatter) for the worker.
68	    /// This should be called after the client has sent the workspace configuration.
69	    pub async fn start_worker(&self, options: serde_json::Value) {
70	        *self.tool.write().await = Some(self.builder.build_boxed(&self.root_uri, options.clone()));
71	
72	        *self.options.lock().await = Some(options);
73	    }
74	
75	    /// Initialize file system watchers for the workspace.
76	    /// These watchers are used to watch for changes in the lint configuration files.
77	    /// The returned watchers will be registered to the client.
78	    pub async fn init_watchers(&self) -> Vec<Registration> {
79	        // clone the options to avoid locking the mutex
80	        let options_json = { self.options.lock().await.clone().unwrap_or_default() };
81	
82	        let tool_guard = self.tool.read().await;
83	        let Some(tool) = tool_guard.as_ref() else {
84	            return Vec::new();
85	        };
86	
87	        let patterns = tool.get_watcher_patterns(options_json.clone());
88	        if patterns.is_empty() {
89	            Vec::new()
90	        } else {
91	            vec![registration_watcher_id(&self.root_uri, patterns)]
92	        }
93	    }
94	
95	    /// Check if the worker needs to be initialized with options
96	    pub async fn needs_init_options(&self) -> bool {
97	        self.options.lock().await.is_none()
98	    }
