100	    /// Remove all internal cache for the given URI, if any.
101	    pub async fn remove_uri_cache(&self, uri: &Uri) {
102	        if let Some(tool) = self.tool.read().await.as_ref() {
103	            tool.remove_uri_cache(uri);
104	        }
105	    }
