#[tokio::test]
async fn tmp_format_outside_workspace() {
    use tokio::sync::RwLock;

    use crate::{ManagerMode, WorkerManager, WorkspaceWorker};

    let mut server = TestServer::new_initialized(
        |client| {
            let builder: Arc<dyn ToolBuilder> = Arc::new(FakeToolBuilder::default());
            let dynamic = WorkspaceWorker::new(
                "file:///".parse().unwrap(),
                Arc::clone(&builder),
                DiagnosticMode::None,
            );
            let manager = WorkerManager::new_with_mode(
                builder,
                ManagerMode::DynamicWithWorkspaces(Box::new(RwLock::new(dynamic))),
            );
            Backend::new(
                client,
                ServerInfo { name: "oxc".to_owned(), version: Some("1.0.0".to_owned()) },
                manager,
            )
        },
        initialize_request(InitializeRequestOptions::default()),
    )
    .await;

    // file OUTSIDE the WORKSPACE root
    let outside = "file:///somewhere/else/file.ts";
    server.send_request(did_open(outside, "const x=1")).await;
    server.send_request(formatting(3, outside)).await;
    let response = server.recv_response().await;
    assert!(response.is_ok());
    let edits: Vec<serde_json::Value> =
        serde_json::from_value(response.result().unwrap().clone()).unwrap();
    assert_eq!(edits.len(), 1);
    assert_eq!(edits[0]["newText"], "const x = 1;");

    server.shutdown(4).await;
}

