        "mjml" => Some("mjml"),
        "html" => Some("html"),
        "scss" => Some("scss"),
        "less" => Some("less"),
        "vue" => Some("vue"),
        "yaml" => Some("yaml"),
        "angular" => Some("component.html"),
        _ => None,
    }
}

pub fn create_fake_file_path_from_language_id(
    language_id: &LanguageId,
    root: &Path,
    uri: &Uri,
) -> Option<PathBuf> {
    let file_extension = get_file_extension_from_language_id(language_id)?;
    // Use the authority (if available) or the last segment of the path as the file name, defaulting to "Untitled" if neither is available
    let mut name = uri.authority().map_or_else(
        || uri.path().rsplit_once('/').map_or_else(|| "Untitled", |(_, s)| s.as_str()),
        |s| s.as_str(),
    );
    // if the last character is `/`, the name will be empty, so we need to check for that as well
    if name.is_empty() {
        name = "Untitled";
    }

    let file_name = format!("{name}.{file_extension}");
    Some(root.join(file_name))
}

/// Run the language server
pub async fn run_lsp(js_config_loader: JsConfigLoaderCb, external_formatter: ExternalFormatter) {
    let version = {
        let mut version = env!("CARGO_PKG_VERSION").to_string();
        if let Some(vp_version) = utils::vp_version() {
            let _ = write!(version, " (VP: {})", vp_version.to_string_lossy());
        }
        version
    };

    let tool: Arc<dyn ToolBuilder> = Arc::new(server_formatter::ServerFormatterBuilder::new(
        js_config_loader,
        external_formatter,
    ));

    // Use `DynamicWithWorkspaces` mode so files outside of any configured workspace
    // (e.g. a file in a parent or sibling directory) are still formatted by a dynamic
    // worker rooted at the file system root. Per-file config resolution ensures the
    // correct configuration is applied regardless of the dynamic worker's root.
    let manager = WorkerManager::new_dynamic_with_workspaces(
        tool,
        "file:///".parse().expect("`file:///` is a valid URI"),
        DiagnosticMode::None,
    );

    run_server("oxfmt".to_string(), version, manager).await;
}

